# -*- coding: utf-8 -*-
"""Horidoro AV — embedded templates.

Every file the installer writes lives here as text. Tokens use @NAME@ style
(never .format() — the shell code contains literal braces). All paths are
per-user; the installer fills the tokens from the current user's environment.

IMPORTANT (verified fixes — do not regress):
  - clamdscan: --multiscan --fdpass, NEVER --stream (known-bad combo)
  - engine readiness: clamdscan --ping --wait (replaces fragile sleep)
  - timeout wrappers: a hung scan can never wedge the chain
  - scan.conf: MaxScanSize 2G, StreamMaxLength 0, MaxRecursion 20
  - post-scan log cleanup strips container-layer housekeeping noise
  - the Bouncer lock-file protocol keeps the engine lifecycle safe

LisMyAngel — provenance marker.
"""

# ---------------------------------------------------------------------------
# scan.conf (written inside the container to /etc/clamd.d/scan.conf)
# ---------------------------------------------------------------------------
SCAN_CONF = r"""LogTime yes
LogClean yes
LogSyslog yes
LocalSocket /tmp/clamd.sock
User clamscan
MaxFileSize 0
MaxScanSize 2G
MaxFiles 0
MaxRecursion 20
MaxDirectoryRecursion 20
LogVerbose yes
OfficialDatabaseOnly no
StreamMaxLength 0
ExcludePath ^@QUARANTINE_DIR@/
# Always-on: container internals are root-owned and verified by their own
# tools; scanning them adds noise (broken symlinks, unreadable files) and
# risks scan stalls. User data in $HOME is still fully scanned.
ExcludePath ^/(var/)?home/[^/]+/\.local/share/containers/storage/overlay
ExcludePath ^/(var/)?home/[^/]+/\.local/share/containers/storage/overlay-containers
@EXCLUSIONS@"""

# ---------------------------------------------------------------------------
# The 4 shell scripts (host files; they drive the container)
# ---------------------------------------------------------------------------
UPDATE_SH = r"""#!/bin/bash
# Horidoro AV - virus database update (managed by the app)
LOG_FILE="@LOG_DIR@/update_history.log"
# Horidoro AV notification sound (honors the Settings toggle; best-effort)
_snd() { grep -q '"sounds_enabled"[[:space:]]*:[[:space:]]*true' "$HOME/.config/horidoro-av/state.json" 2>/dev/null && { paplay "@SOUNDS_DIR@/$1.wav" 2>/dev/null || aplay -q "@SOUNDS_DIR@/$1.wav" 2>/dev/null; } || true; }
echo "[$(date)] --- Starting Horidoro AV database update ---" >> "$LOG_FILE"
distrobox enter -n @CONTAINER@ -- sudo freshclam >> "$LOG_FILE" 2>&1
if [ $? -eq 0 ]; then
    echo "[$(date)] Update Successful." >> "$LOG_FILE"
    _snd update-complete
else
    echo "[$(date)] Update FAILED. Check log for details." >> "$LOG_FILE"
    _snd an-error-occurred
fi
echo "------------------------------------------" >> "$LOG_FILE"
"""

DAILY_SH = r"""#!/bin/bash
# Horidoro AV - daily sensitive scan (managed by the app)
LOG_FILE="@LOG_DIR@/daily_scan.log"
LOCK_FILE="@TMP_DIR@/horidoro_scan.lock"
export DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/$(id -u)/bus
# Horidoro AV notification sound (honors the Settings toggle; best-effort)
_snd() { grep -q '"sounds_enabled"[[:space:]]*:[[:space:]]*true' "$HOME/.config/horidoro-av/state.json" 2>/dev/null && { paplay "@SOUNDS_DIR@/$1.wav" 2>/dev/null || aplay -q "@SOUNDS_DIR@/$1.wav" 2>/dev/null; } || true; }

# Only one scan at a time (daily/monthly/right-click/manual share this lock).
# The lock file is separate from the Bouncer file on purpose: the Bouncer
# rewrites ITS file with sed (inode swap), which would defeat flock.
exec 9>>"$LOCK_FILE.flock"
if ! flock -n 9; then
    echo "[$(date)] skipped - another scan is already running" >> "$LOG_FILE"
    notify-send -u low -i security-high "Horidoro AV" "Daily scan skipped - another scan is already running." 2>/dev/null
    exit 0
fi

bash @SCRIPT_DIR@/update.sh
mkdir -p @TMP_DIR@ @QUARANTINE_DIR@

distrobox enter -n @CONTAINER@ -- bash -c "
    touch \"$LOCK_FILE\"
    echo \"daily\" >> \"$LOCK_FILE\"

    if ! pgrep -x \"clamd\" > /dev/null; then
        sudo clamd -c @CONF@ && echo \"Horidoro AV engine ACTIVE\"
        clamdscan --ping --wait > /dev/null 2>&1
    fi

    if [ "@DAILY_PATHS_SET@" = "1" ]; then
        timeout --kill-after=30s 6h clamdscan --multiscan --fdpass \
                  --move=@QUARANTINE_DIR@ \
                  --log=\"$LOG_FILE\" \
@DAILY_PATHS@
    else
        echo \"[$(date)] skipped - no daily scan targets configured\" >> \"$LOG_FILE\"
        notify-send -u low -i security-high \"Horidoro AV\" \"Daily scan skipped - no scan targets set yet (Settings -> Scan targets).\" 2>/dev/null
    fi

    sed -i '/daily/d' \"$LOCK_FILE\"
    if [ ! -s \"$LOCK_FILE\" ] || [ \$(tr -d '[:space:]' < \"$LOCK_FILE\" | wc -c) -eq 0 ]; then
        sudo pkill -9 clamd && echo \"Horidoro AV engine STOPPED\"
        rm -f \"$LOCK_FILE\"
    fi
"

# record origin paths of newly quarantined files (restore-to-origin)
while IFS= read -r t; do
    b=$(basename "$t")
    if [ -f "@QUARANTINE_DIR@/$b" ]; then
        echo "$b|$t" >> "@TMP_DIR@/origins.tmp"
    fi
done <<'EOF'
@DAILY_PATHS_CLEAN@
EOF

# Log clean-up: strip harmless container-layer housekeeping noise
sed -i -e '/Not supported file type/d' \
       -e '/traverse_to: Failed open/d' \
       -e '/for safe quarantine action/d' \
       "$LOG_FILE"

# Keep the log bounded (~1 month of daily runs)
if [ "$(wc -l < "$LOG_FILE" 2>/dev/null || echo 0)" -gt 5000 ]; then
    tail -n 5000 "$LOG_FILE" > "$LOG_FILE.tmp" && mv "$LOG_FILE.tmp" "$LOG_FILE"
fi

INFECTED=$(grep "Infected files:" "$LOG_FILE" | tail -n 1 | awk '{print $3}')
if [ -z "$INFECTED" ]; then
    notify-send -u critical -i dialog-error "Horidoro AV" "Daily scan failed. Check logs."
    _snd an-error-occurred
elif [ "$INFECTED" -eq "0" ]; then
    notify-send -u low -i security-high "Horidoro AV" "Daily scan complete - system clean."
    _snd scan-complete
else
    notify-send -u critical -i dialog-error "Horidoro AV" "$INFECTED threats found and quarantined!"
    _snd threat-detected
fi
"""

