RIGHT_CLICK_SH = r"""#!/bin/bash
# Horidoro AV - right-click scan (managed by the app)
LOG_FILE="@LOG_DIR@/right_click_scan.log"
LOCK_FILE="@TMP_DIR@/horidoro_scan.lock"
export DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/$(id -u)/bus
# Horidoro AV notification sound (honors the Settings toggle; best-effort)
_snd() { grep -q '"sounds_enabled"[[:space:]]*:[[:space:]]*true' "$HOME/.config/horidoro-av/state.json" 2>/dev/null && { paplay "@SOUNDS_DIR@/$1.wav" 2>/dev/null || aplay -q "@SOUNDS_DIR@/$1.wav" 2>/dev/null; } || true; }

notify-send -u low "Horidoro AV" "Scanning selection..."
mkdir -p @TMP_DIR@ @QUARANTINE_DIR@

# Only one scan at a time (see daily_scan.sh for the rationale).
exec 9>>"$LOCK_FILE.flock"
if ! flock -n 9; then
    echo "[$(date)] skipped - another scan is already running" >> "$LOG_FILE"
    notify-send -u low -i security-high "Horidoro AV" "Right-click scan skipped - another scan is already running." 2>/dev/null
    exit 0
fi

for TARGET in "$@"; do
    # Fedora Atomic mounts home at /var/home inside the container; on
    # traditional distros (Debian/Ubuntu/Mint...) it stays at /home. Only
    # rewrite when the host actually has the Atomic /var/home layout.
    if [ -d /var/home ]; then
        TARGET=$(echo "$TARGET" | sed 's|^/home/|/var/home/|')
    fi

    distrobox enter -n @CONTAINER@ -- bash -c "
        touch \"$LOCK_FILE\"
        echo \"rightclick\" >> \"$LOCK_FILE\"

        if ! pgrep -x \"clamd\" > /dev/null; then
            sudo clamd -c @CONF@ && echo \"Horidoro AV engine ACTIVE\"
            clamdscan --ping --wait > /dev/null 2>&1
        fi

        timeout --kill-after=30s 2h clamdscan --multiscan --fdpass \
                  --move=@QUARANTINE_DIR@ \
                  --log=\"$LOG_FILE\" \
                  \"$TARGET\"

        sed -i '/rightclick/d' \"$LOCK_FILE\"
        if [ ! -s \"$LOCK_FILE\" ] || [ \$(tr -d '[:space:]' < \"$LOCK_FILE\" | wc -c) -eq 0 ]; then
            sudo pkill -9 clamd && echo \"Horidoro AV engine STOPPED\"
            rm -f \"$LOCK_FILE\"
        fi
    "
    # record origin of a newly quarantined file (restore-to-origin)
    b=$(basename "$TARGET")
    if [ -f "@QUARANTINE_DIR@/$b" ]; then
        echo "$b|$TARGET" >> "@TMP_DIR@/origins.tmp"
    fi
done

sed -i -e '/Not supported file type/d' \
       -e '/traverse_to: Failed open/d' \
       -e '/for safe quarantine action/d' \
       "$LOG_FILE"

# Keep the log bounded
if [ "$(wc -l < "$LOG_FILE" 2>/dev/null || echo 0)" -gt 5000 ]; then
    tail -n 5000 "$LOG_FILE" > "$LOG_FILE.tmp" && mv "$LOG_FILE.tmp" "$LOG_FILE"
fi

INFECTED=$(grep "Infected files:" "$LOG_FILE" | tail -n 1 | awk '{print $3}')
if [ -z "$INFECTED" ]; then
    notify-send -u critical -i dialog-error "Horidoro AV" "Right-click scan failed. Check logs."
    _snd an-error-occurred
elif [ "$INFECTED" -eq "0" ]; then
    notify-send -u low -i security-high "Horidoro AV" "Selection is clean."
    _snd scan-complete
else
    notify-send -u critical -i dialog-error "Horidoro AV" "$INFECTED threats found and quarantined!"
    _snd threat-detected
fi
"""

